}

import { GoogleGenAI } from "@google/genai";
import { SpaceGroup } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function getSpaceGroupInsights(group: SpaceGroup) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Explain the crystallographic properties and physical significance of the Fedorov space group #${group.number} (${group.symbol}). Discuss its symmetry elements, typical materials that crystallize in this group, and any unique features. Keep it professional and scientific.`,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error fetching AI insights. Please check your API configuration.";
  }
}

import React, { useMemo } from 'react';
import { SpaceGroup, CrystalSystem } from '../types';

interface LatticeVisualizerProps {
  group: SpaceGroup;
}

const LatticeVisualizer: React.FC<LatticeVisualizerProps> = ({ group }) => {
  const points = useMemo(() => {
    const p = [];
    const size = 10;
    const step = 40;
    const offset = 20;

    // Abstract visualization logic based on Crystal System
    for (let x = 0; x < 5; x++) {
      for (let y = 0; y < 5; y++) {
        for (let z = 0; z < 2; z++) {
          let px = x * step + offset;
          let py = y * step + offset;

          // Apply simple geometric transforms based on crystal system
          if (group.crystalSystem === CrystalSystem.Monoclinic) {
            px += y * 10;
          } else if (group.crystalSystem === CrystalSystem.Trigonal) {
            px += (y % 2) * (step / 2);
          } else if (group.crystalSystem === CrystalSystem.Cubic) {
            // Standard grid
          }

          p.push({ x: px, y: py, z });
        }
      }
    }
    return p;
  }, [group]);

  return (
    <div className="w-full aspect-square bg-slate-900/50 rounded-xl border border-slate-700/50 overflow-hidden relative group">
      <div className="absolute inset-0 flex items-center justify-center opacity-10 pointer-events-none">
        <span className="text-8xl font-black text-slate-100">{group.symbol}</span>
      </div>
      <svg viewBox="0 0 240 240" className="w-full h-full">
        {/* Connections */}
        {points.map((p, i) => (
          points.map((p2, j) => {
            const dist = Math.sqrt(Math.pow(p.x - p2.x, 2) + Math.pow(p.y - p2.y, 2));
            if (dist > 0 && dist < 45) {
              return (
                <line 
                  key={`l-${i}-${j}`} 
                  x1={p.x} y1={p.y} x2={p2.x} y2={p2.y} 
                  stroke="rgba(94, 234, 212, 0.2)" 
                  strokeWidth="0.5" 
                />
              );
            }
            return null;
          })
        ))}
        {/* Points */}
        {points.map((p, i) => (
          <circle 
            key={i} 
            cx={p.x} cy={p.y} 
            r={p.z === 0 ? 3 : 1.5} 
            fill={p.z === 0 ? "#5eead4" : "#2dd4bf"} 
            className="transition-all duration-500 hover:r-5"
          />
        ))}
      </svg>
      <div className="absolute bottom-4 left-4 right-4 text-xs text-slate-400 italic">
        * Abstract representation of {group.crystalSystem} symmetry constraints
      </div>
    </div>
  );
};

export default LatticeVisualizer;

