import React, { useMemo } from 'react';
import { SpaceGroup, CrystalSystem } from '../types';

interface LatticeVisualizerProps {
  group: SpaceGroup;
  isSashaMode: boolean;
}

const LatticeVisualizer: React.FC<LatticeVisualizerProps> = ({ group, isSashaMode }) => {
  const points = useMemo(() => {
    const p = [];
    const step = 45;
    const offset = 30;

    for (let x = 0; x < 4; x++) {
      for (let y = 0; y < 4; y++) {
        for (let z = 0; z < 2; z++) {
          let px = x * step + offset;
          let py = y * step + offset;

          if (group.crystalSystem === CrystalSystem.Monoclinic) {
            px += y * 12;
          } else if (group.crystalSystem === CrystalSystem.Trigonal) {
            px += (y % 2) * (step / 2);
          } else if (group.crystalSystem === CrystalSystem.Cubic) {
            // Perfect grid
          }

          p.push({ x: px, y: py, z, id: `${x}-${y}-${z}` });
        }
      }
    }
    return p;
  }, [group]);

  return (
    <div className={`w-full aspect-square bg-[#0a0f1e] rounded-2xl border-2 transition-all duration-700 overflow-hidden relative ${isSashaMode ? 'border-fuchsia-500/30' : 'border-teal-500/20'}`}>
      {/* Background Grid */}
      <div className="absolute inset-0 opacity-10 pointer-events-none" 
           style={{ backgroundImage: 'radial-gradient(circle, #5eead4 1px, transparent 1px)', backgroundSize: '20px 20px' }} />

      {/* Sasha Overlay Interferences */}
      {isSashaMode && (
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="w-full h-full animate-[pulse_4s_infinite] opacity-20 pointer-events-none"
               style={{ background: 'conic-gradient(from 180deg at 50% 50%, #d946ef 0deg, transparent 360deg)' }} />
        </div>
      )}

      <svg viewBox="0 0 240 240" className="w-full h-full relative z-10">
        <defs>
          <filter id="glow">
            <feGaussianBlur stdDeviation="1.5" result="coloredBlur"/>
            <feMerge>
              <feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        </defs>

        {/* Connections */}
        {points.map((p, i) => (
          points.slice(i + 1).map((p2, j) => {
            const dist = Math.sqrt(Math.pow(p.x - p2.x, 2) + Math.pow(p.y - p2.y, 2));
            if (dist > 0 && dist < 50) {
              return (
                <line 
                  key={`l-${p.id}-${p2.id}`} 
                  x1={p.x} y1={p.y} x2={p2.x} y2={p2.y} 
                  stroke={isSashaMode ? "rgba(217, 70, 239, 0.4)" : "rgba(94, 234, 212, 0.3)"} 
                  strokeWidth={isSashaMode ? "1" : "0.5"}
                  className="transition-colors duration-1000"
                />
              );
            }
            return null;
          })
        ))}

        {/* Lattice Points */}
        {points.map((p) => (
          <g key={p.id}>
            {isSashaMode && (
              <circle 
                cx={p.x} cy={p.y} r="6" 
                fill="none" stroke="#d946ef" strokeWidth="0.5" 
                className="animate-ping opacity-30" 
              />
            )}
            <circle 
              cx={p.x} cy={p.y} 
              r={p.z === 0 ? 3.5 : 2} 
              fill={isSashaMode ? "#f5d0fe" : "#5eead4"}
              filter="url(#glow)"
              className="transition-all duration-700"
            />
          </g>
        ))}
      </svg>

      <div className="absolute top-4 right-4 flex items-center gap-2">
        <div className={`w-2 h-2 rounded-full ${isSashaMode ? 'bg-fuchsia-500 animate-pulse' : 'bg-teal-500'}`} />
        <span className="text-[10px] uppercase tracking-widest font-bold text-white/40">
          {isSashaMode ? 'Sasha USP Active' : 'Fedorov Standard'}
        </span>
      </div>
    </div>
  );
};

export default LatticeVisualizer;

